def idle(base, kit, *, require_idle=True):
    value = base.database_json(kit, WORK_SQL)
    if value["schema"] not in {"0016", "0017", "0018", "0019", "0020"}:
        raise RuntimeError("Unexpected staging schema")
    if value["groups"] != 1:
        raise RuntimeError("Approved test group missing; no groups created automatically")
    if require_idle and any(
        value[k] for k in ("active_ads", "publications", "ambiguous_sanctions", "jobs")
    ):
        raise RuntimeError(
            "Test work needs review: "
            + json.dumps(value, sort_keys=True)
            + "; pause scheduled ads in the existing test bot; no state deleted"
        )
    print(
        "ReadOnlyWorkCheck=PASS; ConfirmedActiveSanctionsPreserved="
        + str(value["active_sanctions"])
        + "; ArchivedActiveSchedulesIgnored="
        + str(value.get("archived_active_schedules", 0)),
        flush=True,
    )
    return value


