MIGRATE = r"""
import asyncio,json,os,sys
import asyncpg
from alembic import command
from alembic.config import Config

def quote(value):return '"'+value.replace('"','""')+'"'
async def snapshot(before=None):
    db=await asyncpg.connect(os.environ['DATABASE_URL'].replace('postgresql+asyncpg:','postgresql:'))
    try:
        if before is None:
            tables=await db.fetch("SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename<>'alembic_version' ORDER BY tablename")
            meta={}
            for table in tables:
                name=table['tablename']
                cols=await db.fetch("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position",name)
                meta[name]={'columns':[r['column_name'] for r in cols]}
                if name=='audit_events':
                    meta[name]['max_id']=await db.fetchval('SELECT COALESCE(max(id),0) FROM audit_events')
        else:meta=before
        result={}
        for name, info in meta.items():
            fields=[]
            for col in info['columns']:
                expr=quote(col)
                if before is None and name=='ad_assignment_policies':
                    change={'mode':"'EXISTING'",'auto_activate':'false','reconcile_at':'NULL','version':'version+1'}.get(col)
                    if change:expr="CASE WHEN mode='FUTURE' THEN "+change+' ELSE '+expr+' END'
                fields.append(expr+' AS '+quote(col))
            where=' WHERE id<='+str(info['max_id']) if name=='audit_events' else ''
            query='SELECT count(*) AS n,md5(COALESCE(string_agg(digest,\'\' ORDER BY digest),\'\')) AS hash FROM (SELECT md5(row_to_json(x)::text) AS digest FROM (SELECT '+','.join(fields)+' FROM '+quote(name)+where+') x) d'
            row=await db.fetchrow(query)
            result[name]={**info,'n':row['n'],'hash':row['hash']}
        return result
    finally:await db.close()
try:
    cfg=json.load(sys.stdin);os.environ['DATABASE_URL']=cfg.pop('DATABASE_URL');cfg.clear()
    before=asyncio.run(snapshot())
    config=Config('/app/alembic.ini')
    command.upgrade(config,'0020');command.check(config)
    after=asyncio.run(snapshot(before))
    if before!=after:raise RuntimeError('Existing row preservation mismatch')
    print('ADS_MIGRATION20=PASS; ExistingRowsVerified=True',flush=True)
except BaseException as error:
    print('ADS_MIGRATION20_STOP='+type(error).__name__,flush=True)
    sys.exit(1)
"""


def run_task(base, kit, images, env, *, db_name, source=None):
    mounts = kit.mounts()
    if source:
        old = "type=bind,src=" + str(kit.ROOT / "source") + ",dst=/app,readonly"
        mounts[mounts.index(old)] = "type=bind,src=" + str(source) + ",dst=/app,readonly"
    name = kit.PREFIX + "-ads-migration20"
    if kit.docker(["ps", "-a", "--filter", "name=^/" + name + "$", "--format", "{{.Names}}"]):
        raise RuntimeError("Existing migration container preserved; inspect before retrying")
    url = env["DATABASE_URL"].rsplit("/", 1)[0] + "/" + db_name
    value = kit.docker(
        [
            "run",
            "--rm",
            "-i",
            *kit.common(name, "384m", "0.5"),
            "--network",
            kit.PREFIX + "-data",
            *mounts,
            images[kit.BASE_IMAGE],
            "python",
            "-c",
            MIGRATE,
        ],
        data=json.dumps({"DATABASE_URL": url}),
        timeout=120,
    )
    if "ADS_MIGRATION20=PASS; ExistingRowsVerified=True" not in value:
        raise RuntimeError("Schema/drift/history check did not confirm success")


def backup_and_rehearse(base, kit, images, env, replacements):
    import shutil

    directory = kit.ROOT / ("auto-ads-backup-" + uuid.uuid4().hex)
    directory.mkdir(mode=0o700)
    pg = kit.PREFIX + "-postgres"
    dump = kit.docker(
        [
            "exec",
            pg,
            "pg_dump",
            "-U",
            "safecheck_staging",
            "-d",
            "safecheck_staging",
            "--no-owner",
            "--no-privileges",
        ],
        timeout=120,
    )
    if not dump or len(dump.encode()) > 64 * 1024 * 1024:
        raise RuntimeError("Unexpected test dump size; no migration attempted")
    base.write_file(directory / "database.sql", dump.encode(), 0o600)
    kit.private_json(directory / "context.json", kit.private_read(kit.ROOT / "context.json"))
    candidate = directory / "candidate"
    shutil.copytree(kit.ROOT / "source", candidate)
    # Non-root migration container needs only this reviewed, non-secret source.
    # The parent remains private until mounts are resolved by the Docker daemon.
    for name, content in replacements.items():
        path = candidate / name
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o755)
        path.write_bytes(content)
        path.chmod(0o644)
    for path in (candidate, *candidate.rglob("*")):
        if path.is_symlink() or not (path.is_dir() or path.is_file()):
            raise RuntimeError("Unsafe rehearsal source entry")
        path.chmod(0o755 if path.is_dir() else 0o644)
    db = "auto_ads_rehearsal_" + uuid.uuid4().hex
    kit.docker(["exec", pg, "createdb", "-U", "safecheck_staging", db])
    success = False
    try:
        kit.docker(
            [
                "exec",
                "-i",
                pg,
                "psql",
                "-X",
                "-q",
                "-v",
                "ON_ERROR_STOP=1",
                "-U",
                "safecheck_staging",
                "-d",
                db,
            ],
            data=dump,
            timeout=120,
        )
        run_task(base, kit, images, env, db_name=db, source=candidate)
        success = True
    finally:
        if success:
            kit.docker(["exec", pg, "dropdb", "-U", "safecheck_staging", db])
    print("PrivateBackup=PASS; MigrationRehearsal=PASS; Backup=" + str(directory), flush=True)
    return directory


def apply(base, kit, lookup, args, context):
    runtime = verify_runtime(base, kit, context)
    client = client_for(args.client_id, context)
    replacements = incoming(base)
    images = kit.private_read(kit.ROOT / "images.json")
    kit.docker(["image", "inspect", images[kit.BASE_IMAGE]])
    kit.resources()
    before = kit.fingerprint()
    if before != context["production_before"]:
        raise RuntimeError("Production baseline changed; no test process stopped")
    for suffix in ("postgres", "redis"):
        if not kit.owned(kit.PREFIX + "-" + suffix)["State"]["Running"]:
            raise RuntimeError("Existing test database/cache not running; no recreation attempted")
    for suffix in ("login", "staffcheck", "enroll"):
        if kit.docker(
            [
                "ps",
                "-a",
                "--filter",
                "name=^/" + kit.PREFIX + "-" + suffix + "$",
                "--format",
                "{{.Names}}",
            ]
        ):
            raise RuntimeError("Other test setup process exists")
    idle(base, kit)
    print("Only @RedTrustBot staging will be updated; no automatic ad activation.", flush=True)
    token = getpass.getpass("RedTrustBot token (hidden, NOT production): ").strip()
    if not token.startswith("8986848376:"):
        raise RuntimeError("Wrong test bot ID; no process stopped")
    result = json.loads(
        kit.docker(
            [
                "run",
                "--rm",
                "-i",
                *kit.common(kit.PREFIX + "-ads-preflight", "256m", "0.5"),
                "--network",
                "bridge",
                *kit.mounts(),
                images[kit.BASE_IMAGE],
                "python",
                "-c",
                PREFLIGHT,
            ],
            data=json.dumps({"token": token}),
            timeout=45,
        )
    )
    if result.get("ok") is not True:
        raise RuntimeError("Read-only test identity check: " + str(result.get("code")))
    env = base.bootstrap(kit, token)
    token = ""
    name = kit.PREFIX + "-bot"
    stopped = False
    try:
        if base.bot_exists(kit) and base.validate_bot(kit)["State"]["Running"]:
            kit.docker(["stop", "--time", "45", name])
        if base.bot_exists(kit) and base.validate_bot(kit)["State"]["Running"]:
            raise RuntimeError("Test bot did not stop")
        stopped = True
        idle(base, kit)
        backup = backup_and_rehearse(base, kit, images, env, replacements)
        if kit.fingerprint() != before:
            raise RuntimeError("Production baseline changed before migration")
        base.update_code(kit, lookup, context, replacements)
        run_task(base, kit, images, env, db_name="safecheck_staging")
        path = kit.ROOT / "runtime" / "runtime.py"
        if path.read_text() != runtime:
            raise RuntimeError("Runtime changed during upgrade")
        base.write_file(backup / "runtime.py", runtime.encode(), 0o600)
        temporary = path.with_name("runtime.auto-ads-new.py")
        base.write_file(temporary, runtime_for(base, kit, client).encode(), 0o644)
        temporary.replace(path)
        updated = kit.private_read(kit.ROOT / "context.json")
        updated["auto_ads_client_id"] = client
        temporary = kit.ROOT / "context.auto-ads-new.json"
        kit.private_json(temporary, updated)
        temporary.replace(kit.ROOT / "context.json")
        if base.bot_exists(kit):
            kit.docker(["rm", name])  # Never -v; no database/cache/session recreation.
        kit.HEAD = CODE_HEAD
        base.start_existing(kit, images, env)
        if kit.fingerprint() != before:
            raise RuntimeError("Production baseline changed during isolated test upgrade")
    except BaseException:
        if stopped and base.bot_exists(kit) and base.validate_bot(kit)["State"]["Running"]:
            kit.docker(["stop", "--time", "45", name])
        print(
            "AUTO_ADS_TEST_STOP: preserve backups and existing data; no automatic rollback/retry.",
            flush=True,
        )
        raise
    finally:
        env.clear()
    print("AUTO_ADS_STAGING=HEALTHY; Schema=0020; HEAD=" + CODE_HEAD, flush=True)
    print(
        "DBPreserved=True; RedisPreserved=True; SessionPreserved=True; ProductionBaselineUnchanged=True",
        flush=True,
    )
    print(
        "NEXT: open @RedTrustBot privately, send /ads. Ads may publish ONLY in test group -1004454398792.",
        flush=True,
    )
    print(
        "ClientTestID=" + str(args.client_id or "not configured; owner-only private testing"),
        flush=True,
    )
    print(
        "No ads activated or Telegram messages/sanctions sent by this updater. Live acceptance is still required.",
        flush=True,
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["apply", "status"])
    parser.add_argument("--client-id", type=int)
    args = parser.parse_args()
    if args.client_id is not None and (args.client_id <= 0 or args.client_id == 8986848376):
        raise RuntimeError("Use a consenting human test account numeric ID")
    if os.geteuid() != 0:
        raise RuntimeError("Use sudo -n python3")
    os.umask(0o077)
    base = predecessor()
    kit = base.imported(base.SETUP, base.SETUP_SHA, "auto_ads_original_setup")
    lookup = base.imported(base.LOOKUP, base.LOOKUP_SHA, "auto_ads_original_lookup")
    context = kit.private_read(kit.ROOT / "context.json")
    kit.HEAD = context.get("head")
    if kit.HEAD not in {base.OLD, base.MIDDLE, *base.REVIEWED_SOURCE_SHA}:
        raise RuntimeError("Unknown test revision; no automatic overwrite")
    kit.load()
    lock = os.open(
        kit.ROOT / ".warning-upgrade.lock", os.O_WRONLY | os.O_CREAT | os.O_NOFOLLOW, 0o600
    )
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        base.verify_source(kit, lookup, kit.HEAD)
        if args.action == "status":
            kit.status()
            state = idle(base, kit, require_idle=False)
            print("TestWork=" + json.dumps(state, sort_keys=True), flush=True)
            print("AutoAdsCandidate=" + str(kit.HEAD == CODE_HEAD), flush=True)
        else:
            apply(base, kit, lookup, args, context)
    finally:
        os.close(lock)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("AUTO_ADS_TEST_STOP=Interrupted", flush=True)
        sys.exit(130)
    except Exception as error:
        # Docker/library raw output may contain secrets: report sanitized type/message only.
        print("AUTO_ADS_TEST_STOP=" + type(error).__name__ + ": " + str(error), flush=True)
        sys.exit(1)
